import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { schemaSnapshot } from "../../../../packages/plugin/src/features/magic-context/schema-fingerprint";

// Isolate even incidental logger/config writes made by migration dependencies.
const sandbox = mkdtempSync(join(tmpdir(), "mc-context-schema-"));
process.env.HOME = sandbox;
process.env.XDG_DATA_HOME = sandbox;
process.env.XDG_CONFIG_HOME = sandbox;
process.env.XDG_CACHE_HOME = sandbox;
process.env.MAGIC_CONTEXT_LOG_PATH = join(sandbox, "magic-context.log");
process.env.NODE_ENV = "test";

try {
    const root = fileURLToPath(new URL("../../../..", import.meta.url));
    const output = resolve(process.argv[2]);
    const { Database } = await import(join(root, "packages/plugin/src/shared/sqlite.ts"));
    const { runMigrations, LATEST_MIGRATION_VERSION } = await import(
        join(root, "packages/plugin/src/features/magic-context/migrations.ts")
    );
    const { initializeDatabase, LATEST_SUPPORTED_VERSION: fence } = await import(
        join(root, "packages/plugin/src/features/magic-context/storage-db.ts")
    );
    if (!Number.isInteger(fence) || fence !== LATEST_MIGRATION_VERSION) {
        throw new Error(`TypeScript fence ${fence} differs from migration chain ${LATEST_MIGRATION_VERSION}`);
    }
    const db = new Database(join(sandbox, "context.db"));
    initializeDatabase(db);
    runMigrations(db);
    const master = db.prepare("SELECT type, name, tbl_name, sql FROM sqlite_master ORDER BY type, name").all() as {
        type: string; name: string; tbl_name: string; sql: string | null;
    }[];
    const snapshot = schemaSnapshot(db);
    const tables = snapshot.tables;
    const migrations = db.prepare("SELECT version, description FROM schema_migrations ORDER BY version").all() as {
        version: number; description: string;
    }[];
    const shadows = new Set((db.prepare("PRAGMA table_list").all() as { name: string; type: string }[])
        .filter(row => row.type === "shadow").map(row => row.name));
    const seeds = tables.filter(table => !shadows.has(table.name) && !table.name.startsWith("sqlite_") &&
        table.name !== "schema_migrations" && !master.find(row => row.name === table.name)?.sql?.startsWith("CREATE VIRTUAL TABLE"))
        .map(table => {
            const columns = table.columns.map(column => column[0] as string);
            const name = `'${table.name.replaceAll("'", "''")}'`;
            const rows: unknown[][] = db.prepare(`SELECT * FROM ${name}`).all().map((row: Record<string, unknown>) => columns.map(column =>
                column === "activated_at" ? ":applied_at" : row[column]));
            return { name: table.name, columns, rows };
        }).filter(table => table.rows.length > 0);
    writeFileSync(output, JSON.stringify({ fence, seeds, snapshot }, null, 2) + "\n");
    if (process.argv[3]) {
        const rows = db.prepare("SELECT type, name, sql FROM sqlite_master ORDER BY rowid").all() as {
            type: string; name: string; sql: string | null;
        }[];
        let sql = "-- Generated by generate.ts from the real TypeScript migration chain.\n";
        sql += `PRAGMA user_version = ${snapshot.user_version};\n\n`;
        // Skip shadow tables, autoindexes and sqlite_sequence: replaying the DDL recreates them.
        sql += rows.filter(row => row.sql && !row.name.startsWith("sqlite_") && !shadows.has(row.name))
            .map(row => row.sql + ";\n").join("\n");
        // Wall-clock application times are supplied by the bootstrap, not pinned in the schema.
        sql += "\nINSERT INTO schema_migrations (version, description, applied_at) VALUES\n";
        sql += migrations.map(row => `(${row.version}, '${row.description.replaceAll("'", "''")}', :applied_at)`)
            .join(",\n") + ";\n";
        for (const seed of seeds) {
            const quoted = (name: string) => `"${name.replaceAll('"', '""')}"`;
            const literal = (value: unknown) => value === ":applied_at" ? ":applied_at" : value === null ? "NULL" :
                typeof value === "string" ? `'${value.replaceAll("'", "''")}'` : String(value);
            sql += `\nINSERT INTO ${quoted(seed.name)} (${seed.columns.map(quoted).join(", ")}) VALUES\n`;
            sql += seed.rows.map(row => `(${row.map(literal).join(", ")})`).join(",\n") + ";\n";
        }
        if (master.some(row => row.name === "sqlite_stat1")) {
            // SQLite reserves this table name; ANALYZE must create it rather than replayed DDL.
            sql += "\nANALYZE;\n";
            if (!master.some(row => row.name === "sqlite_stat4")) {
                // STAT4-enabled SQLite builds create an extra table absent from the TypeScript schema.
                sql += "DROP TABLE IF EXISTS sqlite_stat4;\n";
            }
        }
        writeFileSync(resolve(process.argv[3]), sql);
    }
    db.close();
    console.log(`TypeScript migrations: ${migrations.length}; fence: ${fence}; schema objects: ${master.length}; tables: ${tables.length}`);
} finally {
    rmSync(sandbox, { recursive: true, force: true });
}
